 let mut entities=0;native::entities(&mut entities,1,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported Semio animation native format"))}let schema=native::text(&mut reader,control)?;let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut timelines=control.allocate_vec::<AnimTimeline>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let name=match reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?{0=>None,1=>Some(native::text(&mut reader,control)?),_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native timeline name presence"))};let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut channels=control.allocate_vec::<AnimChannel>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let node=native::text(&mut reader,control)?;let property=match reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?{0=>AnimTargetProperty::Translation,1=>AnimTargetProperty::Rotation,2=>AnimTargetProperty::Scale,3=>AnimTargetProperty::Weights,4=>AnimTargetProperty::Custom{name:native::text(&mut reader,control)?},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio native target property"))};let target=AnimTarget{node,property};let interpolation=interpolation(reader.read_u8().map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?)?;let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut keyframes=control.allocate_vec::<AnimKeyframe>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let t=f64(&mut reader)?;let value=value_binary(&mut reader,control,limits,&mut entities)?;keyframes.push(AnimKeyframe{t,value});control.step()?;}Ok::<_,ValueError>(())})?;channels.push(AnimChannel{target,interpolation,keyframes});control.step()?;}Ok::<_,ValueError>(())})?;timelines.push(AnimTimeline{name,channels});control.step()?;}Ok::<_,ValueError>(())})?;
 if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Semio animation native trailing bytes"))}Ok(SemioAnimationSnapshot{schema,timelines})
